mapper.select:
SELECT c.id, c.campus_id AS campusId, c.name, c.type, c.location, c.description, c.opening_hours AS openingHours, c.status, c.average_score AS averageScore FROM canteen c WHERE c.status = #{status}
AND c.campus_id = #{campusId}
AND c.type = #{type}
ORDER BY c.sort_order ASC, c.id ASC
